<div class="topline"><span>ONE THING AT A TIME</span><span>Make space to concentrate.</span></div><header class="page-header"><div><h1>A little time, well spent.</h1><p class="muted">Study in focused blocks. Record the time you actually spend.</p></div></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<div class="two-col"><section class="card focus-card"><p class="eyebrow"><?= $active ? e(ucfirst($active['kind'])).' SESSION' : 'READY WHEN YOU ARE' ?></p>
<?php if ($active): $elapsed=FocusService::elapsed($active); ?><h2><?= e($active['subject']) ?></h2><div class="focus-time" data-focus-timer data-status="<?= e($active['status']) ?>" data-total="<?= e($active['target_minutes']*60) ?>" data-elapsed="<?= e($elapsed) ?>" data-rendered="<?= e(time()) ?>"><?= e(sprintf('%02d:%02d',intdiv(max(0,$active['target_minutes']*60-$elapsed),60),max(0,$active['target_minutes']*60-$elapsed)%60)) ?></div><p class="muted" data-focus-state><?= e(ucfirst($active['status'])) ?></p><form action="/focus/<?= e($active['id']) ?>/action" method="post" class="timer-actions"><?= csrf_field() ?><button name="action" value="<?= $active['status']==='running' ? 'pause' : 'resume' ?>"><?= $active['status']==='running' ? 'Pause' : 'Resume' ?></button><button class="secondary" name="action" value="finish">Finish & save</button><button class="quiet" name="action" value="cancel">Cancel</button></form><p class="footnote">The timer survives navigation and app restarts. Saved time is capped at the planned duration; finishing early records only elapsed time.</p>
<?php else: ?><div class="focus-time">Ready.</div><p class="muted">Choose your next study block below.</p><form class="stack" action="/focus/start" method="post"><?= csrf_field() ?><label>Subject / intention<input name="subject" maxlength="150" required placeholder="What will you work on?"></label><div class="form-grid"><label>Minutes<input name="minutes" type="number" min="1" max="120" value="25" required></label><label>Session type<select name="kind"><option value="study">Study / focus</option><option value="break">Break</option></select></label></div><button>Start session</button></form><?php endif; ?></section>
<section class="card"><p class="eyebrow">TODAY’S COMPLETED STUDY TIME</p><div class="hero-number"><?= $history ? e($minutes).' <small>minutes</small>' : '<span class="no-data">No data yet</span>' ?></div><h3>Your recent sessions</h3><?php if (!$history): ?><div class="empty"><h3>A first session is a good start.</h3><p>Your actual study minutes and completed sessions will appear here.</p></div><?php else: foreach ($history as $session): ?><div class="simple-row"><span><strong><?= e($session['subject']) ?></strong><small><?= e(ucfirst($session['kind'])) ?> · <?= e($session['status']) ?> · <?= e(substr($session['started_at'],0,10)) ?></small></span><span><?= e(number_format(FocusService::elapsed($session)/60,1)) ?> min</span></div><?php endforeach; endif; ?></section></div>
